import {createResumeOptimizer} from './resume-optimizer.mjs';
import {createWorkspaceStore,workspaceKey,applicationStatuses,safePostingLink,companyKey} from './workspace-store.mjs?v=optimizer-016';
import {createOffersPanel} from './offer-workspace.mjs?v=optimizer-016';
import {appendJobLinks} from './job-links.mjs';
export function mountWorkspace({storage=localStorage,getChatId,getLastReply,getContext,openKeySettings,isAIEnabled=()=>true,isBusy=()=>false,openChat,ask,notify}){
 const store=createWorkspaceStore(storage),$=s=>document.querySelector(s);
 const el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;};
 const button=(text,fn,cls='chip')=>{const b=el('button',text,cls);b.type='button';b.addEventListener('click',fn);return b;};
 const run=fn=>{try{fn();render();}catch(e){notify(e.message||'Could not save this workspace.');}};
 const nav=el('nav',undefined,'workspace-tabs');nav.setAttribute('role','tablist');nav.setAttribute('aria-label','Career workspace');
 const panels=new Map();let selected='chat',researchPending='',researchMessage='',manualFormOpen=false,manualDraft={};
 const titles={chat:'Chat',optimizer:'Resume Optimizer',plan:'Career Plan',offers:'Offers',jobs:'Recommended Jobs',applications:'Applications',employers:'Employer Research',favorites:'Favorite Companies'};
 for(const [id,title]of Object.entries(titles)){
  const tab=button(title,()=>show(id),'workspace-tab');tab.id='tab-'+id;tab.dataset.tab=id;tab.setAttribute('role','tab');tab.setAttribute('aria-controls',id==='chat'?'chat-scroll':'workspace-'+id);nav.append(tab);
  if(id!=='chat'){const panel=el('section',undefined,'workspace-panel');panel.id='workspace-'+id;panel.setAttribute('role','tabpanel');panel.setAttribute('aria-labelledby',tab.id);panel.hidden=true;panels.set(id,panel);}
 }
 const optimizer=createResumeOptimizer({document,panel:panels.get('optimizer'),getContext,getChatId,isAIEnabled,isBusy,ask,openKeySettings,showChat:id=>{if(id)openChat(id);show('chat');},notify});
 const offerPanel=createOffersPanel({document,panel:panels.get('offers'),store,notify,discuss:offers=>{if(isBusy()){notify('Wait for the current reply before discussing offers.');return;}show('chat');ask('Help me compare these job offers. Use my stated priorities, flag missing information and terms to verify.',{offers});}});
 $('.workspace > header').after(nav);for(const panel of panels.values())$('.workspace').append(panel);
 $('#chat-scroll').setAttribute('role','tabpanel');$('#chat-scroll').setAttribute('aria-labelledby','tab-chat');
 function show(id){selected=id;$('#chat-scroll').hidden=id!=='chat';$('.composer-area').hidden=id!=='chat';for(const [key,p]of panels)p.hidden=key!==id;for(const b of nav.children){const on=b.dataset.tab===id;b.setAttribute('aria-selected',String(on));b.tabIndex=on?0:-1;}render();}
 nav.addEventListener('keydown',event=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const tabs=[...nav.children],i=tabs.findIndex(b=>b.dataset.tab===selected),n=event.key==='Home'?0:event.key==='End'?tabs.length-1:(i+(event.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;show(tabs[n].dataset.tab);tabs[n].focus();});
 const heading=(p,title,desc)=>{p.replaceChildren(el('h1',title),el('p',desc,'workspace-intro'));};
 const empty=(p,text,label,fn)=>{const box=el('div',undefined,'workspace-empty');box.append(el('p',text));if(label)box.append(button(label,fn));p.append(box);};
 const discuss=(item,prompt)=>{show('chat');openChat(item.chatId||'');ask(prompt+'\n\nSaved context:\n'+(item.text||[item.title,item.employer,item.location,item.url,item.notes].filter(Boolean).join('\n')).slice(0,12000));};
 function plans(state){
  const p=panels.get('plan');heading(p,'Your career plans','Plans created with the coach are saved here, including earlier versions. Revisit one to keep working on it.');
  p.append(button('Create a career plan',()=>{show('chat');ask('Create a practical four-week career plan based on my experience and goals. Ask for any essential context you still need.');}));
  p.append(button('Save last chat reply as a plan',()=>run(()=>{const text=getLastReply?.();if(!text)throw Error('Open the chat containing your plan first.');store.savePlan({title:'Plan saved from chat',text},getChatId());})));
  if(!state.plans.length)return empty(p,'No plan saved yet. Ask the coach to create one, and it will appear here.');
  for(const plan of state.plans){const card=el('article',undefined,'workspace-card');card.append(el('h2',plan.title),el('small',new Date(plan.createdAt).toLocaleDateString()+' · '+(plan.chatId===getChatId()?'Current chat':'Saved plan')));const prose=el('p',undefined,'saved-prose');appendJobLinks(prose,plan.text);card.append(prose);
   for(const [i,w]of plan.weeks.entries()){const label=el('label',undefined,'workspace-milestone'),check=el('input');check.type='checkbox';check.checked=plan.completed.includes(i);check.addEventListener('change',()=>run(()=>store.completeWeek(plan.id,i,check.checked)));label.append(check,el('span',w.week+' · '+w.title+' — '+w.text));card.append(label);}
   const tools=el('div',undefined,'workspace-actions');tools.append(button('Discuss this plan',()=>discuss(plan,'Help me review and update this saved career plan.')),button('Remove plan',()=>{if(confirm('Remove this saved plan? Its original chat will remain.'))run(()=>store.remove('plans',plan.id));}));card.append(tools);p.append(card);}
 }
 function postingCard(job,tracker=false){
  const card=el('article',undefined,'workspace-card');card.append(el('h2',job.title||'Job posting'),el('p',[job.employer,job.location].filter(Boolean).join(' · '),'job-company'));
  if(job.salary)card.append(el('p','Salary: '+job.salary));if(job.posted)card.append(el('p','Posted: '+job.posted));card.append(el('small',(job.query==='Added manually'?'Added manually ':'Retrieved ')+new Date(job.seenAt).toLocaleDateString()+' · Confirm availability on the employer page.'));
  const actions=el('div',undefined,'workspace-actions');if(safePostingLink(job.url)){const link=el('a','View posting / apply ↗','chip');link.href=job.url;link.target='_blank';link.rel='noopener noreferrer';actions.append(link);}
  actions.append(button('Discuss with coach',()=>discuss(job,'Help me assess this job against my experience and prepare the next application step.')));
  if(job.employer){actions.append(button('Research employer',()=>{show('employers');startResearch(job.employer,job.title);}));const saved=store.read().companies.find(c=>c.key===companyKey(job.employer));actions.append(button(saved?.favorite?'Company favorited ★':'Favorite company ☆',()=>run(()=>store.saveCompany({company:job.employer,role:job.title},getChatId(),{favorite:true}))));}
  if(!tracker)actions.append(button(job.tracked?'View in Applications':'Track application',()=>{run(()=>store.updateJob(job.id,{tracked:true}));show('applications');}));card.append(actions);
  if(tracker){const controls=el('div',undefined,'application-controls'),label=el('label','Application status'),select=el('select');select.setAttribute('aria-label','Application status for '+job.title);for(const status of applicationStatuses){const o=el('option',status);o.value=status;select.append(o);}select.value=job.status;select.addEventListener('change',()=>run(()=>store.updateJob(job.id,{status:select.value})));label.append(select);controls.append(label);
   const dl=el('label','Application deadline (optional)'),date=el('input');date.type='date';date.value=job.deadline;date.addEventListener('change',()=>run(()=>store.updateJob(job.id,{deadline:date.value})));dl.append(date);controls.append(dl);
   const nl=el('label','Notes / steps still needed'),notes=el('textarea');notes.rows=3;notes.maxLength=4000;notes.value=job.notes;notes.placeholder='Example: tailor resume, finish cover letter, submit application';nl.append(notes);controls.append(nl,button('Save notes',()=>run(()=>store.updateJob(job.id,{notes:notes.value}))));if(job.appliedAt)controls.append(el('small','Marked applied: '+job.appliedAt));controls.append(button('Stop tracking',()=>run(()=>store.updateJob(job.id,{tracked:false}))));card.append(controls);
  }return card;
 }
 function jobs(state){const p=panels.get('jobs');heading(p,'Recommended jobs','Actual postings found by the coach, using your shared experience and search preferences. Saved results can become outdated.');
  const form=el('form',undefined,'job-search-form'),role=el('input'),location=el('input');role.placeholder='Target role (optional)';role.maxLength=160;role.setAttribute('aria-label','Target job role');location.placeholder='Location or remote preference';location.maxLength=160;location.setAttribute('aria-label','Job location or remote preference');const go=el('button','Find jobs with my experience','chip');go.type='submit';form.append(role,location,go);form.addEventListener('submit',e=>{e.preventDefault();show('chat');ask('Find actual '+(role.value.trim()||'suitable')+' job postings'+(location.value.trim()?' in '+location.value.trim():'')+' based on the experience I have shared. Return individual application links.');});p.append(form);
  if(!state.jobs.length)return empty(p,'No job results saved yet. Run a search above or ask the coach to find actual postings.');for(const job of state.jobs)p.append(postingCard(job));
 }
 function applications(state){const p=panels.get('applications');heading(p,'Your applications','Track your own progress. Opening a posting does not submit an application; mark Applied only after you have submitted it yourself.');
  const tracked=state.jobs.filter(j=>j.tracked),counts=el('div',undefined,'application-counts');for(const status of applicationStatuses)counts.append(el('span',status+': '+tracked.filter(j=>j.status===status).length));p.append(counts);
  const add=button(manualFormOpen?'Hide application form':'Add a job manually',()=>{manualFormOpen=!manualFormOpen;render();if(manualFormOpen)$('#manual-job-title')?.focus();});add.setAttribute('aria-expanded',String(manualFormOpen));add.setAttribute('aria-controls','manual-application-form');p.append(add);
  if(manualFormOpen)p.append(manualApplicationForm());
  if(!tracked.length)return empty(p,'No applications tracked yet. Save a recommended job or add one manually.');
  for(const status of applicationStatuses){const group=el('section',undefined,'application-group');group.append(el('h2',status==='In progress'?'In progress · finish these applications':status));for(const job of tracked.filter(j=>j.status===status))group.append(postingCard(job,true));if(!tracked.some(j=>j.status===status))group.append(el('p','No jobs in this stage.','small-note'));p.append(group);}
 }
 function manualApplicationForm(){
  const form=el('form',undefined,'workspace-card manual-application-form');form.id='manual-application-form';form.noValidate=true;form.setAttribute('aria-labelledby','manual-application-title');const title=el('h2','Add an application');title.id='manual-application-title';form.append(title,el('p','Enter the details below to keep this opportunity in your tracker.','workspace-intro'));
  const grid=el('div',undefined,'manual-application-grid'),fields={};
  const field=(name,label,type='text',required=false,max=240)=>{const box=el('label',undefined,name==='url'||name==='notes'?'manual-field-wide':''),caption=el('span',label),input=el(type==='textarea'?'textarea':type==='select'?'select':'input');input.id='manual-job-'+name;input.name=name;input.setAttribute('aria-describedby','manual-application-error');if(type==='select'){for(const status of applicationStatuses){const option=el('option',status);option.value=status;input.append(option);}}else if(type==='textarea'){input.rows=3;input.maxLength=max;}else {input.type=type;input.maxLength=max;}input.required=required;input.value=manualDraft[name]|| (name==='status'?'To apply':'');input.addEventListener('input',()=>{manualDraft[name]=input.value;error.textContent='';input.removeAttribute('aria-invalid');});box.append(caption,input);grid.append(box);fields[name]=input;return input;};
  field('title','Job title *','text',true,200).placeholder='e.g. Business Analyst';field('employer','Company (optional)','text',false,200).placeholder='Company name';field('location','Location (optional)').placeholder='e.g. Phoenix, AZ or Remote';field('status','Application status','select');field('url','Posting link *','url',true,2000).placeholder='https://company.com/careers/job';field('deadline','Application deadline (optional)','date');field('notes','Notes / steps still needed','textarea',false,4000).placeholder='Tailor resume, finish cover letter, prepare answers…';form.append(grid);
  const error=el('p','', 'manual-form-error');error.id='manual-application-error';error.setAttribute('role','alert');form.append(error);const actions=el('div',undefined,'workspace-actions'),save=el('button','Save application','manual-submit');save.type='submit';actions.append(save,button('Cancel',()=>{manualFormOpen=false;manualDraft={};render();}));form.append(actions);
  form.addEventListener('submit',event=>{event.preventDefault();error.textContent='';const fail=(name,message)=>{error.textContent=message;fields[name].setAttribute('aria-invalid','true');fields[name].focus();};if(!fields.title.value.trim())return fail('title','Enter a job title.');if(!safePostingLink(fields.url.value.trim()))return fail('url','Enter a valid posting link beginning with https://.');try{store.addApplication(Object.fromEntries(Object.entries(fields).map(([name,input])=>[name,input.value])),getChatId());manualFormOpen=false;manualDraft={};render();notify('Application saved to your tracker.');}catch(e){error.textContent=e.message||'Could not save this application. Your entries are still here.';}});
  return form;
 }
 function startResearch(company,role=''){
  if(isBusy()){notify('Wait for the current response before starting research.');return;}
  const message='Research the employer: '+company+'. Target role: '+(role||'general career exploration')+'. Prepare a cited company briefing covering its business, products, dated recent news, careers information and suggested interview questions.';
  if(!isAIEnabled()){show('chat');ask(message);return;}
  researchPending=company;researchMessage='';render();ask(message);
 }
 function companyCard(company,favoriteView=false){
  const card=el('article',undefined,'workspace-card');card.append(el('h2',company.company));if(company.role)card.append(el('p','Target role: '+company.role,'job-company'));
  if(company.checkedAt)card.append(el('small','Researched '+new Date(company.checkedAt).toLocaleDateString()+' · Verify current details using the sources.'));
  if(company.text){const report=el('details',undefined,'company-briefing');report.open=!favoriteView;report.append(el('summary','Company research briefing'));const prose=el('p',undefined,'saved-prose');appendJobLinks(prose,company.text);report.append(prose);if(company.sources.length){report.append(el('h3','Research sources'));for(const source of company.sources){const a=el('a',source.title+' ↗');a.href=source.url;a.target='_blank';a.rel='noopener noreferrer';const p=el('p');p.append(a);report.append(p);}}card.append(report);}
  else card.append(el('p','Research this employer to build a cited briefing.','small-note'));
  const actions=el('div',undefined,'workspace-actions');actions.append(button(company.favorite?'★ Remove favorite':'☆ Favorite company',()=>run(()=>store.updateCompany(company.id,{favorite:!company.favorite}))),button(company.text?'Refresh research':'Research company',()=>{show('employers');startResearch(company.company,company.role);}));
  if(company.text)actions.append(button('Discuss with coach',()=>discuss(company,'Help me prepare for an interview with '+company.company+' using this saved employer research. Treat the saved information as dated and verify any current claims before relying on them.')));
  actions.append(button('Find jobs at this company',()=>{show('chat');ask('Find actual job postings at '+company.company+(company.role?' for '+company.role:'')+'. Use the experience and preferences I have shared.');}));card.append(actions);
  if(favoriteView){const label=el('label','Your company notes'),notes=el('textarea');notes.rows=3;notes.maxLength=4000;notes.value=company.notes;notes.placeholder='Why you are interested, roles to watch, or interview preparation notes';label.append(notes);const controls=el('div',undefined,'application-controls');controls.append(label,button('Save company notes',()=>run(()=>store.updateCompany(company.id,{notes:notes.value}))));card.append(controls);}
  return card;
 }
 function employers(state){const p=panels.get('employers');heading(p,'Research an employer','Explore a company’s business, products, dated news and interview preparation with cited web research. Uses your API key; saved briefings can become outdated.');
  const form=el('form',undefined,'job-search-form'),company=el('input'),role=el('input');company.required=true;company.maxLength=160;company.placeholder='Company name or official website';company.setAttribute('aria-label','Company to research');role.maxLength=160;role.placeholder='Target role (optional)';role.setAttribute('aria-label','Role for employer research');const go=el('button',researchPending?'Researching…':'Research employer','chip');go.type='submit';go.disabled=!!researchPending;form.append(company,role,go);form.addEventListener('submit',event=>{event.preventDefault();if(company.value.trim())startResearch(company.value.trim(),role.value.trim());});p.append(form);
  if(researchPending){const status=el('p','Researching '+researchPending+' using live web sources…','research-status');status.setAttribute('role','status');p.append(status);}else if(researchMessage)p.append(el('p',researchMessage,'research-status'));
  const researched=state.companies.filter(c=>c.text);if(!researched.length)return empty(p,'No employer briefings saved yet. Enter a company above, or choose Research employer on a saved job.');for(const c of researched)p.append(companyCard(c));
 }
 function favorites(state){const p=panels.get('favorites');heading(p,'Your favorite companies','Keep a shortlist of employers, research briefings and personal notes. You can favorite companies from job cards or research results.');
  const form=el('form',undefined,'job-search-form'),name=el('input');name.required=true;name.maxLength=160;name.placeholder='Add a company to your favorites';name.setAttribute('aria-label','Company to favorite');const add=el('button','Favorite company','chip');add.type='submit';form.append(name,add);form.addEventListener('submit',event=>{event.preventDefault();if(name.value.trim())run(()=>store.saveCompany({company:name.value.trim()},getChatId(),{favorite:true}));});p.append(form);
  const saved=state.companies.filter(c=>c.favorite);if(!saved.length)return empty(p,'No favorite companies yet. Add a company above or favorite one while exploring jobs.');for(const c of saved)p.append(companyCard(c,true));
 }
 function render(){try{const state=store.read();if(selected==='optimizer')optimizer.render();if(selected==='plan')plans(state);if(selected==='offers')offerPanel.render();if(selected==='jobs')jobs(state);if(selected==='applications')applications(state);if(selected==='employers')employers(state);if(selected==='favorites')favorites(state);if(!['chat','optimizer'].includes(selected))panels.get(selected).append(el('p','Saved in this browser only. Plans, jobs, companies and notes do not sync across devices. Avoid sensitive details on shared computers.','small-note'));}catch(e){notify(e.message);}}
 window.addEventListener('storage',e=>{if(e.key===workspaceKey)render();});show('chat');
 return {showChat:()=>show('chat'),showOffers:()=>show('offers'),getOffers:()=>store.read().offers.map(({id,...o})=>o),saveAnswer(answer){optimizer.saveAnswer(answer);run(()=>{if(answer.careerPlan)store.savePlan(answer.careerPlan,getChatId());if(answer.jobSearch?.jobs?.length)store.addJobs(answer.jobSearch.jobs,getChatId(),answer.jobSearch.query);if(answer.employerResearch){store.saveCompany(answer.employerResearch,getChatId());researchPending='';researchMessage='Research saved. You can favorite this company or discuss the briefing with Stride.';}});},requestFinished(){optimizer.requestFinished();if(researchPending){researchPending='';researchMessage='Research did not return a saved briefing. Open Chat for details, check your API key, or retry with the exact company name.';render();}},savePlan(plan){run(()=>store.savePlan(plan,getChatId()));},detachChat(id){run(()=>store.detachChat(id));}};
}
